<?php
namespace App\Services;
use App\Contracts\AIProviderInterface;
use App\Models\{Agenda,AiKnowledgeSource,Document,News,Page,Project,Service,Setting};
use Illuminate\Support\Str;

class PortalKnowledgeProvider implements AIProviderInterface
{
    private array $stop=['yang','dan','atau','untuk','dengan','dari','pada','ini','itu','saya','aku','mau','ingin','tolong','bisa','ada','apa','bagaimana','dimana','kapan','halo','hai','bro'];
    public function searchKnowledge(string $query):array{$terms=$this->terms($query);return AiKnowledgeSource::where('is_enabled',true)->get()->map(function($s)use($terms){$text=mb_strtolower($s->title.' '.$s->content);return['score'=>$terms->sum(fn($t)=>str_contains($text,$t)?(str_contains(mb_strtolower($s->title),$t)?4:1):0),'source'=>$s];})->filter(fn($x)=>$x['score']>0)->sortByDesc('score')->take(3)->values()->all();}
    public function respond(string $message,array $history=[]):array
    {
        $q=mb_strtolower(trim($message));$terms=$this->terms($q);$default=['Lihat berita terbaru','Layanan apa saja?','Bagaimana membuat pengaduan?'];
        if(preg_match('/^(halo|hai|hi|selamat|assalamu)/u',$q))return $this->result('Halo! Saya Asisten PUPR Prabumulih. Saya bisa membantu mencari layanan, berita, dokumen, agenda, proyek, profil dinas, dan mengarahkan pengaduan. Apa yang ingin Anda cari?',[],['Berita terbaru','Jam pelayanan','Buat pengaduan']);
        if(str_contains($q,'terima kasih')||$q==='makasih')return $this->result('Sama-sama. Senang bisa membantu. Kalau masih ada kebutuhan lain tentang Dinas PUPR Prabumulih, langsung tanyakan saja.',[],['Lihat layanan','Berita terbaru','Selesai']);
        $exact=$this->searchKnowledge($message);if($exact&&$exact[0]['score']>=8)return $this->result($exact[0]['source']->content.' Sumber: '.$exact[0]['source']->title.'.',['Informasi terkait'=>'/cari?q='.urlencode($message)],$default);
        if(preg_match('/(pengaduan|lapor|rusak|jalan berlubang|drainase mampet|banjir)/u',$q))return $this->result('Untuk melaporkan kerusakan infrastruktur, buka formulir Pengaduan, isi lokasi yang jelas, kategori, uraian kejadian, nomor kontak, dan lampiran foto bila tersedia. Setelah dikirim, sistem memberikan nomor tiket.',['Buat pengaduan sekarang'=>'/pengaduan','Lihat layanan publik'=>'/layanan'],['Apa yang perlu disiapkan?','Bagaimana status laporan?','Kontak dinas']);
        if(preg_match('/(jam|buka|operasional|pelayanan hari)/u',$q))return $this->result('Jam layanan: '.Setting::getValue('service_hours','Senin–Jumat mengikuti jam kerja Pemerintah Kota Prabumulih').'. Untuk perubahan jadwal atau hari libur, gunakan kanal kontak resmi.',['Kontak Dinas PUPR'=>'/kontak'],['Nomor telepon dinas','Alamat kantor','Layanan apa saja?']);
        if(preg_match('/(alamat|telepon|nomor|whatsapp|email|kontak)/u',$q)){$a=Setting::getValue('address','Kota Prabumulih, Sumatera Selatan');$p=Setting::getValue('phone');$e=Setting::getValue('email');return $this->result("Kantor Dinas PUPR berada di {$a}.".($p?" Telepon: {$p}.":'').($e?" Email: {$e}.":'').' Detail kanal resmi tersedia di halaman Kontak.',['Buka halaman kontak'=>'/kontak'],['Jam pelayanan','Buat pengaduan','Profil dinas']);}
        if(preg_match('/(berita|kabar|terbaru)/u',$q)){$items=News::where('status','PUBLISHED')->latest('published_at')->take(3)->get();return $this->result('Berikut publikasi terbaru yang tersedia di portal.',$items->mapWithKeys(fn($x)=>[$x->title=>'/berita/'.$x->slug])->all(),['Cari berita lain','Lihat agenda','Lihat galeri']);}
        if(preg_match('/(agenda|jadwal|kegiatan)/u',$q)){$a=Agenda::where('status','PUBLISHED')->where('start_datetime','>=',now()->startOfDay())->orderBy('start_datetime')->first();return $a?$this->result('Agenda terdekat: '.$a->title.', '.$a->start_datetime->translatedFormat('d F Y H.i').' WIB di '.$a->location.'.',['Lihat semua agenda'=>'/agenda'],['Berita terbaru','Galeri kegiatan']):$this->result('Belum ada agenda mendatang yang dipublikasikan.',['Buka agenda'=>'/agenda'],$default);}
        $r=collect()->merge($this->find(News::where('status','PUBLISHED'),'title','content','/berita/',$terms,'Berita'))->merge($this->find(Service::where('is_published',true),'name','description','/layanan/',$terms,'Layanan'))->merge($this->find(Project::where('is_published',true),'title','description','/proyek/',$terms,'Proyek'))->merge($this->find(Document::where('is_public',true),'title','description','/transparansi/',$terms,'Dokumen'))->merge($this->find(Page::where('status','PUBLISHED'),'title','content','/halaman/',$terms,'Halaman'))->sortByDesc('score')->take(4)->values();
        if($r->isNotEmpty()){$top=$r->first();return $this->result('Saya menemukan informasi yang paling relevan: '.$top['title'].'. '.Str::limit($top['excerpt'],260),$r->mapWithKeys(fn($x)=>[$x['type'].' · '.$x['title']=>$x['url']])->all(),['Cari topik lain','Berita terbaru','Buat pengaduan']);}
        $k=$this->searchKnowledge($message);if($k)return $this->result($k[0]['source']->content,['Informasi terkait'=>'/cari?q='.urlencode($message)],$default);
        return $this->result('Informasi tersebut belum tersedia secara tepat pada basis pengetahuan resmi. Coba sebutkan topik lebih spesifik—misalnya nama layanan, judul dokumen, lokasi proyek, atau jenis pengaduan.',['Cari di seluruh portal'=>'/cari?q='.urlencode($message),'Hubungi petugas'=>'/kontak'],['Layanan publik','Dokumen terbaru','Buat pengaduan']);
    }
    private function find($query,string $title,string $body,string $prefix,$terms,string $type){if($terms->isEmpty())return collect();return $query->get()->map(function($x)use($title,$body,$prefix,$terms,$type){$text=mb_strtolower(($x->{$title}??'').' '.strip_tags($x->{$body}??''));$score=$terms->sum(fn($t)=>str_contains($text,$t)?(str_contains(mb_strtolower($x->{$title}??''),$t)?5:1):0);return compact('score','type')+['title'=>$x->{$title},'excerpt'=>trim(strip_tags($x->{$body}??'')),'url'=>$prefix.$x->slug];})->filter(fn($x)=>$x['score']>0);}
    private function terms(string $q){return collect(preg_split('/[^\pL\pN]+/u',mb_strtolower($q)))->filter(fn($t)=>mb_strlen($t)>2&&!in_array($t,$this->stop))->unique()->values();}
    private function result(string $answer,array $links,array $suggestions):array{return['answer'=>$answer,'links'=>collect($links)->map(fn($url,$label)=>compact('label','url'))->values()->all(),'suggestions'=>$suggestions,'timestamp'=>now()->toIso8601String()];}
    public function chat(string $message):string{return $this->respond($message)['answer'];}public function embed(string $content):array{return[];}public function healthCheck():bool{return AiKnowledgeSource::where('is_enabled',true)->exists();}
}
